using FlexExtractor;
using System.Diagnostics;
using System.Runtime.InteropServices;
static partial class Cases {
 public static void TestParentDeathKillsWorkerAndReleasesLease(){var root=Fresh();var state=typeof(MachineState).GetField("TestRoot",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Static)!;var previous=state.GetValue(null);var local=Path.Combine(root,"state");using var parent=new Process{StartInfo=new ProcessStartInfo(Path.Combine(AppContext.BaseDirectory,"FlexExtractor.Tests.exe")){UseShellExecute=false,CreateNoWindow=true}};parent.StartInfo.ArgumentList.Add("--probe-parent");parent.StartInfo.ArgumentList.Add(root);Program.Check(parent.Start(),"probe parent failed to start");try{Program.Check(SpinWait.SpinUntil(()=>File.Exists(Path.Combine(root,"worker.pid")),8000),"probe child pid not found");var pid=int.Parse(File.ReadAllText(Path.Combine(root,"worker.pid")));parent.Kill(false);Program.Check(parent.WaitForExit(5000),"parent not stopped");Program.Check(SpinWait.SpinUntil(()=>!Harness.Alive(pid),5000),"orphan worker survived parent death");state.SetValue(null,local);using var owner=new OwnerLease();}finally{if(!parent.HasExited){parent.Kill(true);parent.WaitForExit(5000);}state.SetValue(null,previous);}}
}
static partial class Harness {
 [StructLayout(LayoutKind.Sequential)]struct BasicProcess{public IntPtr Reserved1,Peb,Reserved2a,Reserved2b,Pid,ParentPid;}
 [DllImport("ntdll.dll")]static extern int NtQueryInformationProcess(IntPtr process,int info,out BasicProcess data,int size,out int returned);
 public static bool Alive(int pid){try{using var p=Process.GetProcessById(pid);return !p.HasExited;}catch(ArgumentException){return false;}}
 public static int ProbeParent(string root){root=Path.GetFullPath(root);if(!root.StartsWith(Path.Combine(AppContext.BaseDirectory,"selftest-data"),StringComparison.OrdinalIgnoreCase))return 65;typeof(MachineState).GetField("TestRoot",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Static)!.SetValue(null,Path.Combine(root,"state"));using var owner=new OwnerLease();var c=new Config{WatchRoot=Path.Combine(root,"watch"),DispenseItems=[new(){Token="31",StationName="probe",SaveFolder=Path.Combine(root,"out")}],WorkerTimeoutSec=60};var running=WorkerRunner.RunAsync(owner,c,"probe-hang",DateTime.UtcNow,CancellationToken.None);int pid=0;var watch=Stopwatch.StartNew();while(pid==0&&watch.ElapsedMilliseconds<5000){foreach(var p in Process.GetProcessesByName("FlexExtractor.Worker")){using(p){try{if(NtQueryInformationProcess(p.Handle,0,out var data,Marshal.SizeOf<BasicProcess>(),out _)==0&&data.ParentPid.ToInt64()==Environment.ProcessId)pid=p.Id;}catch(System.ComponentModel.Win32Exception){}}}Thread.Sleep(20);}if(pid==0)return 66;File.WriteAllText(Path.Combine(root,"worker.pid"),pid.ToString());running.GetAwaiter().GetResult();return 0;}

}
